// Server implements the strict server interface generated by oapi-codegen.
type Server struct{
    dynamoClient *dynamodb.Client // AWSと通信するためのクライアントを追加
}

func NewServer(client *dynamodb.Client) *Server {
    return &Server{
        dynamoClient: client,
    }
}

// Ensure Server implements the interface at compile time.
var _ api.StrictServerInterface = (*Server)(nil)

var errNotImplemented = fmt.Errorf("not implemented")

