// 2. 【トイレ登録】トイレの情報を新しく登録する関数
// POST /toilets
func (s *Server) CreateToilet(ctx context.Context, request api.CreateToiletRequestObject) (api.CreateToiletResponseObject, error) {
    // 1. 保存するデータの「塊」を作る
    // 設計図(request.Body)のデータを、DB保存用の形式に整理します
    item := map[string]interface{}{
        "toiletId":           uuid.New().String(), // ここで本物のランダムなIDを生成！
        "name":               request.Body.Name,
        "brand":              string(request.Body.Brand),
        "lat":                request.Body.Lat,
        "lng":                request.Body.Lng,
        "imageKey":           request.Body.ImageKey,
        "maleCount":          request.Body.MaleCount,
        "femaleCount":        request.Body.FemaleCount,
        "multipurposeCount":  request.Body.MultipurposeCount,
        "requiresPermission": request.Body.RequiresPermission,
        "createdAt":          time.Now().Format(time.RFC3339),
    }

    // 2. GoのデータをDynamoDBが理解できる形式に変換（Marshal）
    av, err := attributevalue.MarshalMap(item)
    if err != nil {
        return nil, fmt.Errorf("failed to marshal item: %w", err)
    }

    // 3. DynamoDBに「これ保存して！」とお願いする（PutItem）
    _, err = s.dynamoClient.PutItem(ctx, &dynamodb.PutItemInput{
        TableName: aws.String("ToiletsTable"), // 保存先のテーブル名
        Item:      av,
    })
    if err != nil {
        return nil, fmt.Errorf("failed to put item to DynamoDB: %w", err)
    }

    // 4. 成功レスポンスを返す
    return api.CreateToilet201JSONResponse{
        // ... (以下、先ほどと同じレスポンス処理)
    }, nil
}

